// Workflow script: one batch of the compile-path ladder climb.
//
// What it does, stage by stage, and why: explorations/coordinator/climb-batch-workflow.md
// (the manual) and explorations/coordinator/process-engineering/batch-redesign.md (the
// practice it builds, with the evidence and the cost of each choice). A batch is a manifest
// change and nothing else: the coordinator splices the block between the MANIFEST and END
// MANIFEST lines from the batch's generator (explorations/compile-ladder/plan-<N>/manifest/)
// and launches. Before the launch the coordinator builds the batch's one base build; each
// rung worker makes its own worktree, seeded from it:
//   Workflow({scriptPath: 'explorations/coordinator/climb-batch-workflow.js',
//             args: {base: '<the full hash of the base>', baseBuild: '<the base build, a built worktree at that commit>'}})
//
// The shape since the redesign of 2026-10-08: each rung's worker does the rung test first;
// its skeptic checks it and fixes what it finds, test first; a judge rules only on a fix
// the skeptic marks contested or on a rung it cannot fix, and a repair round runs only on
// the judge's word; no second skeptic. Then the gather lands the approved rungs on main,
// the merged-diff review and the gate run side by side, and the commit stage lands the
// gate's tables, runs the microGPT walk check and pushes. The batch writes no skill text:
// each rung's revival-change material goes into the batch's RECORD.md, and the standing
// skill writer writes the skill from it after the landing, before a cold read
// (explorations/reviews/skills-agenda-audit.md, "Proposed fix to the mechanism"). Every
// agent is pinned to Opus but a judge's second ruling on the same rung or tree, which runs
// on Fable (POSITIONS.md, "The judge's rulings."). Every prompt
// points to the fortress-repo skill for how to build, test, run the old code, wait and
// commit, and says only what the role does in this batch. No backticks and no non-ASCII
// character anywhere in this file.
//
// Every agent() call goes through callAgent ("An agent that comes back with nothing"),
// which runs a role again, up to two more times, when its agent returns nothing; a usage
// or rate limit, or a rung worker, skeptic or judge that returns nothing after its
// attempts, stops the run there and decides nothing, and resumeFromRunId with the same
// script and args then runs that role again.

export const meta = {
  name: 'fortress-climb-batch',
  description: 'One batch of Fortress compile-ladder rungs in seeded worktrees: each rung done test first by its worker and checked by a skeptic that fixes what it finds, a judge only on a contested fix or a refusal; gathered onto main, reviewed beside one gate, landed and pushed; its revival-change material left in the batch record for the skill writer',
  phases: [
    { title: 'Rung', detail: 'the rung done test first in its own seeded worktree, committed and pushed to its wip/ branch as it goes' },
    { title: 'Skeptic', detail: 'the rung checked by reading and by programs of its own on the old and new code; what it finds it fixes, test first, and it marks a fix contested when nothing on record settles it' },
    { title: 'Judge', detail: 'Opus for a first ruling, Fable for a second on the same rung or tree: only on a contested fix, a refusal, a worker that stopped, a blocking review or a red gate' },
    { title: 'Gather', detail: 'each approved rung applied to main in one commit with its record folded, the new ledger rows added through ledger.py, the rows it fixed closed' },
    { title: 'Review', detail: 'the merged diff, the skeptics\' fixes and the folded record read as a whole, once, beside the gate' },
    { title: 'Gate', detail: 'compileAll, the suites at four threads, testSpecData once a rung brings it, the atomic runs, the ladder regression, the checker count, and the distance stage beside them, reported and never red' },
    { title: 'Commit', detail: 'the gate\'s tables landed, the microGPT walk check run, the batch checked for skill text it should not have written, main pushed to its three branches, the worktrees removed; no push while a step that cannot be undone is unlifted' },
  ],
}

const OPUS = 'opus'   // every agent but a judge's second ruling
const FABLE = 'fable' // a judge's second ruling on the same rung or tree
const judgeTier = (priorRuling) => priorRuling ? { model: FABLE } : { model: OPUS }
const BASE = args && args.base
if (!BASE) throw new Error('args.base is required: the commit every wip/ branch is cut from')
// The batch's one base build (POSITIONS.md, "Nothing is built or run twice on the same code."): a
// worktree at BASE that the coordinator built once before the launch. Every rung worktree is
// seeded from it (tools/seed-worktree.sh), and the old code runs from it through
// tools/old-fortress.sh, each rung with a private caches folder in its worktree's tmp/; nobody
// builds, compiles or runs anything else in it.
const BASE_BUILD = args && args.baseBuild
if (typeof BASE_BUILD !== 'string' || !/^\/[A-Za-z0-9._\/-]+$/.test(BASE_BUILD) || /\/$/.test(BASE_BUILD))
  throw new Error('args.baseBuild is required: the absolute path of the worktree at the base, built once before the launch (climb-batch-workflow.md, "Before the launch"), with no trailing slash, space or quote')
const TOOLS = 'explorations/coordinator/tools'
const SEED = BASE_BUILD + '/' + TOOLS + '/seed-worktree.sh'
const OLD = BASE_BUILD + '/' + TOOLS + '/old-fortress.sh'   // runs the base's code from the base build
const oldCaches = (rung) => rung.path + '/tmp/old-caches'   // a rung's private caches folder for the old code
const PUSH_BRANCHES = ['claude/worker-brief-fable-vnnuv8', 'blinded-fable']   // every push of main goes to these too (explorations/protocol.md, hard rules)
const MAIN = '/home/user/fortress'
const LEDGER = TOOLS + '/ledger.py'

// ===========================================================================
// MANIFEST - the coordinator replaces everything between this line and the
// "END MANIFEST" line, and changes nothing else in this file.
//
// Generated by explorations/compile-ladder/plan-27/manifest/gen27.py from
// CLIMB-BATCH-27.md (section 4, each rung's section word for word; section 1, the
// manifest fields; section 6, the intro) and the briefings of lists27.py; check27.js checks it.
// Climb batch 27: rungs N, I, F, C, W, S, A, E, G, T, the manifest's order; N lands only with F.
// Per rung: id, slug, path, branch, expectedMinutes (the scatter's start order only),
// writesState, testIsStage, gateJoins (a gate step the rung brings), blurb (one line
// for the batch table), section (the rung's section of the record, read by every role
// on the rung), pointsToReport, briefing and reasons (the facts-extract.sh keys the
// worker reads first, each with its reason), checks (the sub-list the skeptic, a judge
// and a repair round read), expectedMoves (ladder moves declared, none here), and the
// optional landsOnlyWith, expectedCheckerCount and expectedCheckerCrash: N lands only
// with F (fork 1), and no rung declares a checker count or a crash (the count is reported).
// A section keeps the record's few characters outside ASCII as \u escapes.
// No value is set at launch. The base and the base build are args.base and
// args.baseBuild. At most two agents run at once on this box, FIFO (FACTS.md, "The
// Workflow harness runs two agents at once on this box"); the scatter starts the
// longest expected worker first.
// ===========================================================================

const BATCH = '27'
const BATCH_RECORD = 'explorations/coordinator/CLIMB-BATCH-27.md'
const BRIEFING_LISTS = 'explorations/compile-ladder/plan-27/manifest/lists27.py'

const N_SECTION = [
"**The mission.** The territory map shows the library's vectors and matrices beside the number types, with the element bound T extends Number (map/spec-to-implementation.md, section 4.2, its last two paragraphs). Its table of the tower predates the flat number types (P-43), so take the types' shape from the decisions on record. This rung lets a program declare its own number type below Number, so that such a type can meet that bound. It also leaves Number as the team's later prelude has it, a trait that declares nothing (ProjectFortress/LibraryBuiltin/CompilerBuiltin.fss:510-511): each number type converts and compares by its own declarations.",
"",
"**The decisions this rung builds.**",
"- P-160: the one library's Number opens in two steps. The first, walk's reading of the array operators beside AdditiveGroup's own, landed (F-318). This rung is the second: the clause removed from Library/FortressLibrary.fss and .fsi, the reflective QuickCheck generator given a way to generate a Number, Number's = and asFloat taken off the trait (P-165), so that a program's own number type compares by its own = or by the library's fallback = through SEQV (fork N2), and the tests that lean on the clause repaired.",
"- P-165: asFloat and the = built on it leave Number (Library/FortressLibrary.fss:382-408, .fsi:290-295); each of the eight number types and IntLiteral keeps its own asFloat; two numbers of different types compare by = only where a coercion carries one into the other (P-74), and otherwise the program writes the conversion, asFloat(x) = y; the vector norm takes a bound that promises a float, as a fork with a default; the specification's sentence changes with this rung. The team's 2012 library built Number's = on asFloat (git show a874948ac:Library/FortressLibrary.fss, lines 349-373); the prelude's Number declares nothing; Specification/basic-lib/numbers.tex:47-49 is the revival's own text (d9c415395).",
"- What P-165's rule on = needs (fork N7): the fallback opr =(a:Any, b:Any):Boolean = a SEQV b (Library/FortressLibrary.fss:96) applies to every pair without a coercion, and a coercion never changes which declaration runs when one applies without it (Specification/basic/conversions-coercions.tex:470-494). So with Number's = struck and nothing added, the fallback, not a coercion, answers every mixed = (section 5, probe 8). The pairs of = below make the rule hold.",
"- P-44: AnyIntegral's clause stays. Row 551: walk does not check a clause declared outside the main component; its test names Number today. Row 596: its Number half, tests/extendNumber.fss, needs no edit once the clause goes. Row 434: Number's = between a float and an exact number is not transitive; your strike removes that =. Row 440: 0/0 = 0/0 answers true under walk, which Number's = reaches today for every program's type.",
"- This record's section 3, forks 1 to 8, N1 to N5 (9 to 13) and N6 to N8 (32 to 34), give the defaults you build.",
"",
"**What you build.**",
"- The tests first (below).",
"- Delete the clause: comprises { RR64, RR32, QQ, AnyIntegral, IntLiteral } at Library/FortressLibrary.fss:381 and Library/FortressLibrary.fsi:289.",
"- Strike the rest of Number's body: asFloat (.fss:382; .fsi:290-291, with its doc comment) and = with its doc comment (.fss:383-395; .fsi:292-295), and exactValue (.fss:398-408), which only Number's = calls (git grep -n exactValue names besides them only a message of tests/IntLiteralValue.fss:35). Number keeps its header and nothing else, in both files: trait Number extends { AnyAdditiveGroup, AnyMultiplicativeRing } end.",
"- Each type's own asFloat in its api (fork N6): asFloat(self): RR64 in the traits RR64, QQ, ZZ32, ZZ64, NN64 and ZZ, written abstract in Library/FortressLibrary.fsi and without a body in .fss, as Number declares it today; and in the objects RR32, NN32 and IntLiteral of ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi, at their components' headers (FortressBuiltin.fss:241, :396, :504; IntLiteral's answers Float). Put each right before the type's own =: the parser refuses a method before a coercion or a getter ('Coercion declarations should come first.', 'Field/getter/setter declarations should come before method declarations.', probe 8). Without the api lines the phase that binds names, which both paths run, refuses the first library component that calls asFloat, 'Variable asFloat is not defined.' at Library/String.fss:529 (probe 8): a functional method's name reaches a component only through an api that declares it. The traits' bodiless declarations in the component follow the export rule (P-158). The objects' bindings stay as they are (F-311).",
"- The pairs of = (fork N7). The apis declare 21 coercions between the nine types: RR64 from ZZ32, RR32 and IntLiteral; QQ from ZZ32, ZZ64, NN32, NN64, ZZ and IntLiteral; NN64 from NN32 and IntLiteral; ZZ64 from ZZ32, NN32 and IntLiteral; ZZ from ZZ32, ZZ64, NN32, NN64 and IntLiteral; ZZ32 and NN32 from IntLiteral. For each, the wider type T declares opr =(self, b:S):Boolean, which converts b as the coercion does and compares at T, and the narrower type S declares opr =(self, b:T):Boolean, which converts self: 42 declarations, each with its api line. Put each beside its type's own =: Library/FortressLibrary.fss:441 (RR64), :597 (QQ), :740 (ZZ32), :831 (ZZ64), :917 (NN64), :1007 (ZZ); ProjectFortress/LibraryBuiltin/FortressBuiltin.fss:246 (RR32), :400 (NN32), :508 (IntLiteral); and in the apis Library/FortressLibrary.fsi:327, :416, :495, :548, :607, :661, FortressBuiltin.fsi:70, :134, :188. The planner's prototype (section 5, probe 11) wrote each body as do c: T = b; (self = c) end or do c: T = self; (c = b) end, and walk asks for the parentheses ('Equality testing expressions should be parenthesized.'); write the conversion as you find best, and name the form in your report. The library's precedent is IntLiteral's exponent overloads, which convert by b.asZZ32 (Library/FortressLibrary.fss:804).",
"- The comparisons that no pair carries: those of three tests, 10 lines, which the prototype's walk suite fails (section 5, probe 11; below). Write each with its conversion. The library's own comparisons need none: the prototype's suite fails nowhere else. Any other that you find, respell the same way and list.",
"- The vector norm (fork N8): its one declaration over T extends { Number, MultiplicativeRing[\\T\\] } (Library/FortressLibrary.fss:2645, .fsi:1706) replaced by eight, one for each number type, as opr ||[\\nat k\\] me: Vector[\\ZZ32,k\\]||: RR64 = SQRT asFloat(squaredNorm(me)), and at RR64 SQRT squaredNorm(me). squaredNorm stays as it is.",
"- The reflective generator, genType (Library/ReflectiveQuickCheck.fss:25-45): Number as a special case beside Any (:30-32), a fixed choice among the clause's five entries (fork N1). genAnyType's branch 1 => genType(theType[\\Number\\]()).generate(c) (:49-58) then works through it.",
"- Row 551's test: ProjectFortress/tests/XXXComprisesLibraryTraitUnlistedExtender.fss and .test retargeted to another closed trait of the library, AnyIntegral by default (fork N3): its comment, its object and its load_exception_contains key.",
"- The comment of ProjectFortress/tests/ReflectiveNumberTypes.fss:7, \"The reflective generator finds a generator for every type that Number's comprises clause lists.\", made true of the new generator.",
"- The specification (fork N4): Specification/basic-lib/numbers.tex:47-49 says that each number type declares asFloat, with a \\revision callout labelled by your new Appendix I entry, \\seclabel{revival-asfloat}, after \"The single-precision floating-point type\" (Specification/appendices/changes.tex:2659-2735); the same clause of the entry \"The number types\" (changes.tex:578) corrected, which your entry names. The entry follows the skill's specification.md, \"Changing the text: the revision form\", with every item of the form's example: the Working Draft has no such sentence, so quote the revival's text as the original and say that the revival added it (d9c415395); the effect names the pairs of =, the fallback, and row 909, by which walk answers a mixed = that no pair carries; the decision is P-165; the Route C item is the same under route C. The front matter's paragraph changes only if your change makes it false.",
"- Not yours: rung F's sites (fork N5): random, atan2 and printThreadInfo over Number, the RR64 trait's ^ and atan2 over Number (Library/FortressLibrary.fss:485, :494) and Float's ^ at Number (FortressBuiltin.fss:160); AnyIntegral's clause (P-44); walk's load check (F-318); array1 and array2, which give a Vector only at the eight number types (row 721; F-229); FACTS, POSITIONS and the ledger, which the gather folds your record.md into (the manual, \"Rung worker\").",
"",
"**Tests, first.**",

const say = (ok, line) => { if (!ok) bad++; console.log((ok ? 'ok   ' : 'BAD  ') + line) }
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor
{
  const r = cp.spawnSync('node', ['--check', target], { encoding: 'utf8' })
  say(r.status === 0, 'node --check: exit ' + r.status + (r.stderr.trim() ? ' ' + r.stderr.trim().slice(0, 300) : ''))
  let err = null
  try { new AsyncFunction('args', 'agent', 'pipeline', 'parallel', 'log', orig.replace(/^export const meta/m, 'const meta')) } catch (e) { err = e }
  say(!err, 'the harness\'s parse: ' + (err ? 'refused, ' + err.message : 'accepted as an async function body, its export made const'))
  const ticks = orig.match(/\x60/g) || []
  say(!ticks.length && !/[^\x00-\x7f]/.test(orig), 'the script holds ' + ticks.length + ' backtick(s) and ' + ((orig.match(/[^\x00-\x7f]/g) || []).length) + ' non-ASCII character(s)')
  const GATE_FNS = ['gate_summary', 'gate_compare', 'last_landed_summary', 'ladder_filter', 'ladder_compare', 'mg_phases']
  const fnFile = path.join(ROOT, 'explorations/coordinator/tools/gate-functions.sh')
  const g = cp.spawnSync('bash', ['-c', 'source "$1" && declare -F ' + GATE_FNS.join(' ') + ' && declare -f gate_summary', 'x', fnFile], { encoding: 'utf8' })
  say(g.status === 0 && /machine\.sh/.test(g.stdout), 'the gate\'s functions file sources and defines ' + GATE_FNS.join(', ') + ', its gate_summary writing the machine line' + (g.status ? ': exit ' + g.status + ' ' + g.stderr.trim().slice(0, 200) : ''))
}
const body = orig.replace(/^export const meta/m, 'const meta')

// Every section that the script cites by name, of a fortress-repo part ("the skill's tests-writing.md, "The
// order"") or of the batch workflow's manual or the redesign's synthesis, is a heading of that file, its
// backticks and any section number dropped, equal to the name or opening with it. The parts are read from
// SKILL_DIR.
{
  const refs = path.join(SKILL_DIR, 'references')
  const files = {}
  if (fs.existsSync(refs)) for (const f of fs.readdirSync(refs)) if (/\.md$/.test(f) && f !== 'sources.md') files[f] = path.join(refs, f)
  files['climb-batch-workflow.md'] = path.join(ROOT, 'explorations/coordinator/climb-batch-workflow.md')
  files['batch-redesign.md'] = path.join(ROOT, 'explorations/coordinator/process-engineering/batch-redesign.md')
  const text = orig.replace(/\n\s*\/\/ ?/g, ' ')
  const cited = new Map()
  const re = /\b([a-z][a-z-]*\.md)(?:\s+says)?(?:,\s*|\s*\()((?:"[^"]+"(?:;\s*|\s+and\s+|,\s*)?)+)/g
  let m
  while ((m = re.exec(text))) {
    if (!files[m[1]]) continue
    for (const q of m[2].match(/"[^"]+"/g)) { const name = q.slice(1, -1).replace(/\\'/g, "'"); cited.set(m[1] + ' "' + name + '"', [m[1], name]) }
  }
  const missing = []
  for (const [key, [file, name]] of cited) {
